func test_expressions_TestExprs_test_is_star(self *Case, a Args) Value {
	var deep_union, deep_subquery, underscore1 Value
	_ = []Value{deep_union, deep_subquery, underscore1}
	self.Do(1362, func() { Assert(A(Call(G("sqlglot.parse_one"), "*"), "is_star")) })
	self.Do(1363, func() { Assert(A(Call(G("sqlglot.parse_one"), "foo.*"), "is_star")) })
	self.Do(1364, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT * FROM foo"), "is_star")) })
	self.Do(1365, func() { Assert(A(Call(G("sqlglot.parse_one"), "(SELECT * FROM foo)"), "is_star")) })
	self.Do(1366, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT *, 1 FROM foo"), "is_star")) })
	self.Do(1367, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT foo.* FROM foo"), "is_star")) })
	self.Do(1368, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT * EXCEPT (a, b) FROM foo"), "is_star")) })
	self.Do(1369, func() {
		Assert(A(Call(G("sqlglot.parse_one"), "SELECT foo.* EXCEPT (foo.a, foo.b) FROM foo"), "is_star"))
	})
	self.Do(1370, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT * REPLACE (a AS b, b AS C)"), "is_star")) })
	self.Do(1371, func() {
		Assert(A(Call(G("sqlglot.parse_one"), "SELECT * EXCEPT (a, b) REPLACE (a AS b, b AS C)"), "is_star"))
	})
	self.Do(1372, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT * INTO newevent FROM event"), "is_star")) })
	self.Do(1373, func() {
		Assert(A(Call(G("sqlglot.parse_one"), "SELECT * FROM foo UNION SELECT * FROM bar"), "is_star"))
	})
	self.Do(1374, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT * FROM bla UNION SELECT 1 AS x"), "is_star")) })
	self.Do(1375, func() { Assert(A(Call(G("sqlglot.parse_one"), "SELECT 1 AS x UNION SELECT * FROM bla"), "is_star")) })
	self.Do(1376, func() {
		Assert(A(Call(G("sqlglot.parse_one"), "SELECT 1 AS x UNION SELECT 1 AS x UNION SELECT * FROM foo"), "is_star"))
	})
	self.DoAssign(1379, func() { deep_union = M(G("sqlglot.exp"), "select", "1") }, &deep_union)
	self.DoAssign(1380, func() { deep_subquery = M(G("sqlglot.exp"), "select", "1") }, &deep_subquery)
	for _, item_ := range Iter(Call(G("range"), 5000)) {
		underscore1 = item_
		self.DoAssign(1382, func() {
			deep_union = M(G("sqlglot.exp"), "Union", Kw("this", deep_union), Kw("expression", M(G("sqlglot.exp"), "select", "1")))
		}, &deep_union)
		self.DoAssign(1383, func() { deep_subquery = M(G("sqlglot.exp"), "Subquery", Kw("this", deep_subquery)) }, &deep_subquery)
	}
	self.Do(1385, func() { Assert(Not(A(deep_union, "is_star"))) })
	self.Do(1386, func() { Assert(Not(A(deep_subquery, "is_star"))) })
	self.Do(1387, func() {
		Assert(A(M(G("sqlglot.exp"), "Union", Kw("this", deep_union), Kw("expression", M(G("sqlglot.exp"), "select", "*"))), "is_star"))
	})
	self.Do(1388, func() {
		Assert(A(M(G("sqlglot.exp"), "Subquery", Kw("this", M(G("sqlglot.exp"), "Union", Kw("this", deep_union), Kw("expression", M(G("sqlglot.exp"), "select", "*"))))), "is_star"))
	})
	return nil
}

