func test_expressions_TestExprs_test_pipe_and_apply(self *Case, a Args) Value {
	var add_val, add_val_alt, col, added Value
	_ = []Value{add_val, add_val_alt, col, added}
	self.Do(1557, func() {
		add_val = Func("add_val", func(a Args) Value {
			var nb, expr, val, squared Value
			_ = []Value{nb, expr, val, squared}
			expr = a.Get(0, "expr", nil)
			val = a.Get(1, "val", nil)
			squared = a.Get(-1, "squared", nil)
			nb = IfV(squared, func() Value { return Pow(val, 2) }, func() Value { return val })
			return Add(expr, nb)
		})
	})
	self.Do(1561, func() {
		add_val_alt = Func("add_val_alt", func(a Args) Value {
			var val, squared, expr Value
			_ = []Value{val, squared, expr}
			val = a.Get(0, "val", nil)
			squared = a.Get(1, "squared", nil)
			expr = a.Get(2, "expr", nil)
			return Call(add_val, expr, val, Kw("squared", squared))
		})
	})
	self.DoAssign(1564, func() { col = M(G("sqlglot.exp"), "column", "age") }, &col)
	self.DoAssign(1565, func() { added = Call(add_val, col, 5, Kw("squared", true)) }, &added)
	self.Do(1567, func() {
		self.AssertEqual(col, M(col, "apply", Lambda(func(args ...Value) Value {
			var x Value = nil
			if len(args) > 0 {
				x = args[0]
			}
			_ = x
			return x
		})))
	})
	self.Do(1569, func() { self.AssertEqual(M(col, "pipe", add_val, 5, Kw("squared", true)), added) })
	self.Do(1570, func() {
		self.AssertEqual(M(col, "pipe", Lambda(func(args ...Value) Value {
			var e Value = nil
			if len(args) > 0 {
				e = args[0]
			}
			_ = e
			return Call(add_val_alt, 5, true, e)
		})), added)
	})
	return nil
}
